// Stories: short, repetitive, present-tense narration in the register the Gym drills.
// Each line is spoken as one audio file (public/audio/<line id>.mp3, generated by scripts/gen-audio.py).
// Claude-authored – have a native speaker read them before trusting every line.

import type { Token, Role, Morphology, MorphPart } from "./types";

/* A Chunk is a meaningful phrase boundary within a sentence.
   Instead of duplicating text, it references token indices. */
export interface Chunk {
  range: [number, number]; // [start, end) indices into tokens array
  gloss: string;           // natural English for just this chunk
}

export interface StoryLine {
  id: string;        // audio file name
  text: string;      // Tagalog as spoken
  gloss: string;     // natural English
  tokens: Token[];
  voice?: "A" | "B"; // A = female narrator, B = male (dialogue lines for Ben)
  chunks?: Chunk[];  // optional phrase boundaries for progressive disclosure
}

export interface Quiz { q: string; options: string[]; answer: number }

export interface Story {
  id: string;
  title: string;
  titleEn: string;
  blurb: string;
  level: 1 | 2 | 3 | 4;
  newWords?: string[];   // what this story adds on top of the ones before it
  quiz?: Quiz[];         // three quick questions, in Tagalog, at the end
  lines: StoryLine[];
}

type T = [string, Role, string, string?];
type TT = T | string; // a bare string looks the word up in DICT

/* Shared meanings for the words that recur across stories. A line can still override with a full tuple. */
